{
  "items": [
    {
      "name": "Polynomial.sum_zero_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] (f : ℕ → R → S) : Polynomial.sum 0 f = 0",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_X_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] {f : ℕ → R → S} (hf : f 1 0 = 0) : Polynomial.X.sum f = f 1 1",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_C_index",
      "type": " {R : Type u} [Semiring R] {a : R} {β : Type u_1} [AddCommMonoid β] {f : ℕ → R → β} (h : f 0 0 = 0) : (Polynomial.C a).sum f = f 0 a",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_eq_of_subset",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] {p : Polynomial R} (f : ℕ → R → S) (hf : ∀ (i : ℕ), f i 0 = 0) {s : Finset ℕ} (hs : p.support ⊆ s) : p.sum f = ∑ n ∈ s, f n (p.coeff n)",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_smul_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] (p : Polynomial R) (b : R) (f : ℕ → R → S) (hf : ∀ (i : ℕ), f i 0 = 0) : (b • p).sum f = p.sum fun n a => f n (b * a)",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_monomial_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] {n : ℕ} (a : R) (f : ℕ → R → S) (hf : f n 0 = 0) : ((Polynomial.monomial n) a).sum f = f n a",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_add_index",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} [AddCommMonoid S] (p q : Polynomial R) (f : ℕ → R → S) (hf : ∀ (i : ℕ), f i 0 = 0) (h_add : ∀ (a : ℕ) (b₁ b₂ : R), f a (b₁ + b₂) = f a b₁ + f a b₂) : (p + q).sum f = p.sum f + q.sum f",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_smul_index'",
      "type": " {R : Type u} [Semiring R] {S : Type u_1} {T : Type u_2} [DistribSMul T R] [AddCommMonoid S] (p : Polynomial R) (b : T) (f : ℕ → R → S) (hf : ∀ (i : ℕ), f i 0 = 0) : (b • p).sum f = p.sum fun n a => f n (b • a)",
      "module": "Mathlib.Algebra.Polynomial.Basic"
    },
    {
      "name": "Polynomial.sum_over_range'",
      "type": " {R : Type u} {S : Type v} [Semiring R] [AddCommMonoid S] (p : Polynomial R) {f : ℕ → R → S} (h : ∀ (n : ℕ), f n 0 = 0) (n : ℕ) (hn : p.natDegree < n) : p.sum f = ∑ a ∈ Finset.range n, f a (p.coeff a)",
      "module": "Mathlib.Algebra.Polynomial.Degree.Support"
    },
    {
      "name": "Polynomial.sum_over_range",
      "type": " {R : Type u} {S : Type v} [Semiring R] [AddCommMonoid S] (p : Polynomial R) {f : ℕ → R → S} (h : ∀ (n : ℕ), f n 0 = 0) : p.sum f = ∑ a ∈ Finset.range (p.natDegree + 1), f a (p.coeff a)",
      "module": "Mathlib.Algebra.Polynomial.Degree.Support"
    },
    {
      "name": "Polynomial.sum_fin",
      "type": " {R : Type u} {S : Type v} [Semiring R] [AddCommMonoid S] (f : ℕ → R → S) (hf : ∀ (i : ℕ), f i 0 = 0) {n : ℕ} {p : Polynomial R} (hn : p.degree < ↑n) : ∑ i, f (↑i) (p.coeff ↑i) = p.sum f",
      "module": "Mathlib.Algebra.Polynomial.Degree.Support"
    }
  ]
}
